    document.querySelector('#start').addEventListener('click',start);
    function makeBar(enemy){const g=new THREE.Group();const back=new THREE.Mesh(new THREE.PlaneGeometry(1.05,.075),new THREE.MeshBasicMaterial({color:'#101719',transparent:true,opacity:.9,depthWrite:false}));const fill=new THREE.Mesh(new THREE.PlaneGeometry(.98,.045),new THREE.MeshBasicMaterial({color:'#d5fa70',depthWrite:false}));fill.position.z=.006;g.add(back,fill);g.position.y=2.15;enemy.add(g);enemy.userData.bar=fill;enemy.userData.barGroup=g;}
    function face(from,to){const dx=to.x-from.x,dz=to.z-from.z;from.rotation.y=Math.atan2(dx,dz)}
    function targetEnemy(){let best=null,d=Infinity;for(const e of enemies){if(e.userData.hp<=0)continue;const n=e.position.distanceTo(player.position);if(n<d){best=e;d=n}}return best}
    function playerAttack(){if(!running||gameOver||attackTimer>0)return;attackTimer=.52;const t=targetEnemy();if(t&&t.position.distanceTo(player.position)<2.65){t.userData.hp--;t.userData.state='stun';t.userData.timer=.85;t.userData.body.material.emissive=new THREE.Color('#aaff88');t.userData.body.material.emissiveIntensity=.9;updateBar(t);if(t.userData.hp<=0)killEnemy(t);else notify('CLEAN HIT');}setStance('STRIKE')}
    function updateBar(e){if(!e.userData.barGroup)makeBar(e);const ratio=Math.max(0,e.userData.hp/e.userData.maxHp);e.userData.bar.scale.x=ratio;e.userData.bar.position.x=-(1-ratio)*.49;e.userData.bar.material.color.set(ratio<=.34?'#ff786d':'#d5fa70');e.userData.barGroup.visible=ratio<1||wave===3}
    function killEnemy(e){scene.remove(e);enemies=enemies.filter(x=>x!==e);if(enemies.length===0){if(wave<3){document.querySelector('#objective').textContent='The next warden is listening…';setTimeout(()=>{if(running&&!gameOver)spawnWave()},1200)}else finish(true)}}
    function finish(win){running=false;gameOver=true;document.querySelector('#eyebrow').textContent=win?'THE GLASS REMEMBERS':'THE CONSERVATORY CLAIMS YOU';document.querySelector('#title').innerHTML=win?'DAWN<br><em>UNBROKEN</em>':'DUEL<br><em>ENDED</em>';document.querySelector('#desc').textContent=win?'Three wardens, one impossible morning. The echo in your blade goes quiet as the greenhouse fills with light.':'The wardens return to their posts. The conservatory keeps its secrets — for now.';document.querySelector('.brief').innerHTML='<div><b>'+ (win?'DUEL COMPLETE':'ONE MORE TRY')+'</b>'+ (win?'The Sunken Conservatory is yours.':'Read the red flash, parry the lunge, then trust the echo.')+'</div><div><b>YOUR RECORD</b>WARDENS DEFEATED &nbsp;·&nbsp; '+(win?'03':'0'+Math.max(0,wave-1))+' / 03</div>';document.querySelector('#start').textContent=win?'PLAY AGAIN ↗':'RETRY DUEL ↗';document.querySelector('.smallnote').textContent='TIP: THE ECHO STRIKES A MOMENT AFTER A PERFECT PARRY';screen.classList.remove('hidden')}
    function parry(){if(!running||gameOver)return;parryTimer=.48;setStance('PARRY');player.userData.sword.rotation.z=.6;}
    function dash(){if(!running||gameOver||dashTimer>0)return;dashTimer=.27;invuln=.38;const d=moveDir.lengthSq()?moveDir.clone().normalize():new THREE.Vector3(Math.sin(player.rotation.y),0,Math.cos(player.rotation.y));player.position.addScaledVector(d,1.35);player.position.x=THREE.MathUtils.clamp(player.position.x,-8.55,8.55);player.position.z=THREE.MathUtils.clamp(player.position.z,-8.55,8.55);}
    window.addEventListener('keydown',e=>{keys.add(e.code);if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='Space')parry();if(e.code==='ShiftLeft'||e.code==='ShiftRight')dash();if(e.code==='Enter'&&!running)start()});window.addEventListener('keyup',e=>keys.delete(e.code));renderer.domElement.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&e.button===0)playerAttack()});
    document.querySelector('#tAttack').addEventListener('pointerdown',e=>{e.preventDefault();playerAttack()});document.querySelector('#tParry').addEventListener('pointerdown',e=>{e.preventDefault();parry()});document.querySelector('#tDash').addEventListener('pointerdown',e=>{e.preventDefault();dash()});
    let stickId=null,stickVector={x:0,y:0};const stick=document.querySelector('#stick');stick.addEventListener('pointerdown',e=>{stickId=e.pointerId;stick.setPointerCapture(stickId);stickMove(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===stickId)stickMove(e)});stick.addEventListener('pointerup',()=>{stickId=null;stickVector={x:0,y:0}});function stickMove(e){const r=stick.getBoundingClientRect(),x=(e.clientX-r.left-r.width/2)/(r.width/2),y=(e.clientY-r.top-r.height/2)/(r.height/2),m=Math.max(1,Math.hypot(x,y));stickVector={x:x/m,y:y/m}}
    const hazard=new THREE.Mesh(new THREE.RingGeometry(4.5,6.1,80),new THREE.MeshBasicMaterial({color:'#ff514d',transparent:true,opacity:.18,side:THREE.DoubleSide,depthWrite:false}));hazard.rotation.x=-Math.PI/2;hazard.position.y=.075;hazard.visible=false;scene.add(hazard);const hazardLine=new THREE.Mesh(new THREE.TorusGeometry(5.3,.055,8,90),new THREE.MeshBasicMaterial({color:'#ff786d',transparent:true,opacity:.4}));hazardLine.rotation.x=Math.PI/2;hazardLine.position.y=.085;scene.add(hazardLine);let hazardPhase='idle',hazardClock=0;
    function takeHit(){if(invuln>0)return;health--;updateHealth();invuln=.95;player.userData.body.material.emissive=new THREE.Color('#ff382d');player.userData.body.material.emissiveIntensity=1.5;notify('THE GARDEN BITES');setStance('WOUNDED');if(health<=0)finish(false)}
    function makeEcho(pos,dir){const g=new THREE.Group();const blade=new THREE.Mesh(new THREE.BoxGeometry(.09,.08,2.1),mats.blade);blade.rotation.y=Math.PI/2;g.add(blade);g.position.copy(pos);g.position.y=.8;g.rotation.y=Math.atan2(dir.x,dir.z);scene.add(g);echoes.push({mesh:g,time:.38,dir:dir.clone(),origin:pos.clone()});}
    let last=performance.now()/1000;
    function tick(nowMs){requestAnimationFrame(tick);const now=nowMs/1000,dt=Math.min(.04,now-last);last=now;if(!running){renderer.render(scene,camera);return}if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)document.querySelector('#toast').classList.remove('show')}parryTimer=Math.max(0,parryTimer-dt);attackTimer=Math.max(0,attackTimer-dt);dashTimer=Math.max(0,dashTimer-dt);invuln=Math.max(0,invuln-dt);if(hitFlash>0)hitFlash-=dt;
      const mx=(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0)+stickVector.x;const mz=(keys.has('KeyS')||keys.has('ArrowDown')?1:0)-(keys.has('KeyW')||keys.has('ArrowUp')?1:0)+stickVector.y;moveDir.set(mx,0,mz);if(moveDir.lengthSq()>1)moveDir.normalize();if(moveDir.lengthSq()>.01){player.position.addScaledVector(moveDir,dt*(dashTimer>0?0:4.15));player.position.x=THREE.MathUtils.clamp(player.position.x,-8.55,8.55);player.position.z=THREE.MathUtils.clamp(player.position.z,-8.55,8.55);if(!targetEnemy())face(player,new THREE.Vector3(player.position.x+moveDir.x,0,player.position.z+moveDir.z))}
      const target=targetEnemy();if(target)face(player,target.position);player.userData.body.position.y=.83+Math.sin(now*7)*.035*(moveDir.lengthSq()>.01?1:.25);player.userData.sword.rotation.z=attackTimer>0?-.95+Math.sin((.52-attackTimer)/.52*Math.PI)*1.9:parryTimer>0?.55:Math.sin(now*2)*.04;
      if(hazardPhase==='idle'){hazardClock+=dt;if(hazardClock>6){hazardClock=0;hazardPhase='warn';hazard.visible=true;hazard.material.opacity=.13;notify('CRESCENT SWEEP · MOVE INWARD')}}else if(hazardPhase==='warn'){hazardClock+=dt;hazard.material.opacity=.2+Math.sin(now*12)*.08;if(hazardClock>1.8){hazardPhase='active';hazardClock=0;hazard.material.opacity=.58;hazardLine.material.opacity=.9;}}else{hazardClock+=dt;hazard.material.opacity=.36+Math.sin(now*15)*.15;hazardLine.rotation.y+=dt*1.6;if(Math.hypot(player.position.x,player.position.z)>4.5&&Math.hypot(player.position.x,player.position.z)<6.15)takeHit();if(hazardClock>1.35){hazardPhase='idle';hazardClock=0;hazard.visible=false;hazard.material.opacity=.18;hazardLine.material.opacity=.4}}
      for(const e of [...enemies]){if(e.userData.hp<=0)continue;const dist=e.position.distanceTo(player.position);face(e,player.position);e.userData.body.position.y=.83+Math.sin(now*5+e.position.x)*.025;if(e.userData.state==='approach'){if(dist>1.85){const v=new THREE.Vector3().subVectors(player.position,e.position).setY(0).normalize();e.position.addScaledVector(v,dt*e.userData.speed)}e.userData.attackCooldown-=dt;if(e.userData.attackCooldown<=0&&dist<4.2){e.userData.state='tell';e.userData.timer=.8;e.userData.attackCooldown=waveData[wave-1].interval;e.userData.body.material.emissive.set('#ff3d31');e.userData.body.material.emissiveIntensity=1.6;notify('PARRY THE FLASH')}}else if(e.userData.state==='tell'){e.userData.timer-=dt;e.userData.body.material.emissiveIntensity=1.2+Math.sin(now*27)*.9;if(e.userData.timer<=0){e.userData.state='strike';e.userData.timer=.35;const v=new THREE.Vector3().subVectors(player.position,e.position).setY(0).normalize();e.position.addScaledVector(v,.62);if(dist<2.5){if(parryTimer>0){e.userData.state='stun';e.userData.timer=1.15;e.userData.body.material.emissive.set('#c9ff80');e.userData.body.material.emissiveIntensity=1.9;notify('PERFECT RIPOSTE · ECHO RELEASED');setStance('ECHO READY');makeEcho(player.position.clone(),v)}else if(invuln<=0)takeHit();}}}else if(e.userData.state==='strike'){e.userData.timer-=dt;if(e.userData.timer<=0){e.userData.state='approach';e.userData.body.material.emissive.set('#000000');e.userData.body.material.emissiveIntensity=0}}else if(e.userData.state==='stun'){e.userData.timer-=dt;e.userData.body.material.emissiveIntensity=Math.max(0,e.userData.timer);if(e.userData.timer<=0){e.userData.state='approach';e.userData.body.material.emissive.set('#000000');e.userData.body.material.emissiveIntensity=0}}if(e.userData.barGroup){e.userData.barGroup.quaternion.copy(camera.quaternion);}}
      for(let i=echoes.length-1;i>=0;i--){const q=echoes[i];q.time-=dt;q.mesh.position.y=.8+Math.sin((.38-q.time)*15)*.08;q.mesh.material.opacity=Math.max(0,q.time/.38);if(q.time<=0){for(const e of enemies){if(e.position.distanceTo(q.origin)<3.4&&e.userData.hp>0){e.userData.hp--;e.userData.state='stun';e.userData.timer=.8;updateBar(e);notify('ECHO CONNECTED');if(e.userData.hp<=0)killEnemy(e);break}}scene.remove(q.mesh);echoes.splice(i,1)}}
      if(invuln>0)player.visible=Math.floor(now*18)%2===0;else player.visible=true;if(document.querySelector('#stance').textContent==='WOUNDED'&&invuln<=.1)setStance('READY');camera.position.x+=(player.position.x*.25-camera.position.x)*dt*1.3;camera.position.z+=(16+player.position.z*.15-camera.position.z)*dt*1.3;camera.lookAt(player.position.x*.22,0,0);renderer.render(scene,camera)}
    requestAnimationFrame(tick);
    window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8))});
  </script>
</body>
</html>

