55	    function makeFighter(isPlayer){const g=new THREE.Group();const body=new THREE.Mesh(avatarGeo,isPlayer?mats.player:mats.enemy);body.position.y=.83;body.castShadow=true;g.add(body);const robe=new THREE.Mesh(new THREE.ConeGeometry(.54,.82,8),isPlayer?mats.coat:mats.enemy);robe.position.y=.43;robe.rotation.x=Math.PI;robe.castShadow=true;g.add(robe);const head=new THREE.Mesh(new THREE.SphereGeometry(.25,12,9),isPlayer?mats.player:mats.gold);head.position.y=1.55;head.castShadow=true;g.add(head);const visor=new THREE.Mesh(new THREE.BoxGeometry(.4,.1,.25),isPlayer?mats.gold:mats.danger);visor.position.set(0,1.57,.22);g.add(visor);const sword=new THREE.Group();sword.position.set(.35,1.05,.05);const guard=box(sword,0,0,0,.12,.08,.34,mats.gold);guard.rotation.z=.2;const blade=box(sword,0,.42,0,.075,.78,.12,isPlayer?mats.blade:mats.gold);blade.rotation.z=-.1;const pommel=new THREE.Mesh(new THREE.SphereGeometry(.11,8,8),mats.dark);pommel.position.y=-.12;sword.add(pommel);g.add(sword);g.userData={body,sword,head};scene.add(g);return g}
