58	    const waveData=[{name:'THE GLASS WARDEN',hp:2,speed:1.15,interval:2.7,color:'#be7164'},{name:'THE VEIL TWINS',hp:2,speed:1.35,interval:2.25,color:'#d19468'},{name:'THE LAST GARDENER',hp:4,speed:1.55,interval:1.85,color:'#a97b9c'}];
59	    function spawnWave(){wave++;document.querySelector('#wave').textContent=String(wave).padStart(2,'0');const data=waveData[wave-1];enemies=[];const count=wave===2?2:1;for(let i=0;i<count;i++){const e=makeFighter(false);e.position.set((i-(count-1)/2)*2.1,-.01,-4.6);e.rotation.y=Math.PI;e.userData.hp=data.hp;e.userData.maxHp=data.hp;e.userData.state='approach';e.userData.timer=1.2+i*.65;e.userData.attackCooldown=.9+i*.65;e.userData.speed=data.speed;e.userData.name=data.name;e.userData.tint=new THREE.Color(data.color);e.userData.body.material=mats.enemy.clone();e.userData.body.material.color.copy(e.userData.tint);e.userData.robe.material=mats.enemy.clone();e.userData.robe.material.color.copy(e.userData.tint);enemies.push(e)}document.querySelector('#objective').textContent=wave===2?'Two veiled wardens. Keep them in view.':wave===3?'The last gardener has four lives.':'Break the glass warden’s rhythm.';}
